package io.helidon.tracing.opentelemetry;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.function.BiConsumer;

import io.opentelemetry.api.baggage.Baggage;
import io.opentelemetry.api.baggage.BaggageBuilder;
import io.opentelemetry.api.baggage.BaggageEntry;
import io.opentelemetry.api.baggage.BaggageEntryMetadata;
import io.opentelemetry.context.Context;
import io.opentelemetry.context.Scope;

/**
 * A mutable implementation of the OpenTelemetry {@link io.opentelemetry.api.baggage.Baggage} interface.
 * <p>
 * The standard OpenTelemetry {@code Baggage} implementations are immutable; adding an entry produces a brand new
 * instance which then has to be stored in the (also immutable) {@link io.opentelemetry.context.Context}. Doing so from
 * {@link io.helidon.tracing.Span#baggage(String, String)} would force us to make a new context current, leaking an
 * unclosed scope every time baggage is set on an already-active span.
 * <p>
 * Instead this class holds the entries in a mutable map so that {@link #baggage(String, String)} can update the baggage
 * in place without touching the current context. The single instance associated with a span is made current (once) as
 * part of {@link io.helidon.tracing.Span#activate()}, and any subsequent baggage changes are automatically visible
 * through that already-current instance.
 */
class MutableOpenTelemetryBaggage implements Baggage {

    private final Map<String, BaggageEntry> values = new HashMap<>();

    MutableOpenTelemetryBaggage() {
    }

    @Override
    public void forEach(BiConsumer<? super String, ? super BaggageEntry> consumer) {
        values.forEach(consumer);
    }

    @Override
    public Map<String, BaggageEntry> asMap() {
        return Collections.unmodifiableMap(values);
    }

    @Override
    public String getEntryValue(String entryKey) {
        BaggageEntry entry = values.get(entryKey);
        return entry != null ? entry.getValue() : null;
    }

    @Override
    public int size() {
        return values.size();
    }

    @Override
    public BaggageBuilder toBuilder() {
        // Callers expect the builder to update this same baggage instance rather than a fresh copy.
        return new MutableOpenTelemetryBaggageBuilder();
    }

    @Override
    public Scope makeCurrent() {
        // Store this (mutable) baggage instance in the current context and make it current. Because the stored
        // instance is mutable, later calls to baggage(key, value) are reflected without changing the context again.
        return Context.current().with(this).makeCurrent();
    }

    /**
     * Adds or updates a baggage entry without affecting the OpenTelemetry context.
     *
     * @param key   baggage key
     * @param value baggage value
     */
    void baggage(String key, String value) {
        values.put(key, new MutableEntry(value, BaggageEntryMetadata.empty()));
    }

    private record MutableEntry(String value, BaggageEntryMetadata metadata) implements BaggageEntry {
        @Override
        public String getValue() {
            return value;
        }

        @Override
        public BaggageEntryMetadata getMetadata() {
            return metadata;
        }
    }

    private class MutableOpenTelemetryBaggageBuilder implements BaggageBuilder {

        @Override
        public BaggageBuilder put(String key, String value, BaggageEntryMetadata entryMetadata) {
            values.put(key, new MutableEntry(value, entryMetadata));
            return this;
        }

        @Override
        public BaggageBuilder remove(String key) {
            values.remove(key);
            return this;
        }

        @Override
        public Baggage build() {
            return MutableOpenTelemetryBaggage.this;
        }
    }
}
